use std::fs::File;
use std::io::{self, Read};

/// Synchronously reads a packet from `file` into the standard 4096-byte
/// buffer and returns the packet ID parsed from the first two bytes
/// (big-endian).
pub fn vtx_read_packet_id(file: &mut File) -> Result<u16, io::Error> {
    let mut buffer = [0u8; 4096];

    let mut read = 0usize;
    while read < 2 {
        match file.read(&mut buffer[read..]) {
            Ok(0) => break,
            Ok(n) => read += n,
            Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(e),
        }
    }

    if read < 2 {
        return Err(io::Error::new(
            io::ErrorKind::UnexpectedEof,
            "packet shorter than 2 bytes",
        ));
    }

    Ok(u16::from_be_bytes([buffer[0], buffer[1]]))
}

